 const add=()=>setValues([...values,{id:crypto.randomUUID(),name:'New mutation',category:'Physical',quality:'Beneficial',activation:'Conscious',range:'Body',duration:'Instant',targets:'Self',uses:'Once per scene',damage:'None',effect:'Describe the original effect.',exhausted:false,misfire:false,notes:''}]);
