function normalizeTableImport(data:unknown):Tables{
 const wrapper=data as {customTables?:unknown};const source=wrapper&&typeof wrapper==='object'&&wrapper.customTables?wrapper.customTables:data;
 if(!source||typeof source!=='object'||Array.isArray(source))throw new Error('JSON must be an object of table arrays.');
 const imported:Tables={};for(const [key,value] of Object.entries(source as Record<string,unknown>)){if(!Array.isArray(value))continue;const entries=value.map(item=>typeof item==='string'?item:typeof item==='object'&&item&&typeof (item as {text?:unknown}).text==='string'?String((item as {text:string}).text):'').map(item=>item.trim()).filter(Boolean);if(entries.length||value.length===0)imported[key]=entries}
 if(!Object.keys(imported).length)throw new Error('No table arrays were found in this file.');return imported;
}
